package updateverify

import (
	"crypto/sha256"
	"encoding/hex"
	"os"
	"path/filepath"
	"strings"
	"testing"
)

func sha256Hex(data string) string {
	sum := sha256.Sum256([]byte(data))
	return hex.EncodeToString(sum[:])
}

func TestFindDigestAcceptsCommonFormats(t *testing.T) {
	digest := sha256Hex("exposely binary")
	other := sha256Hex("installer")

	sums := strings.Join([]string{
		"# generated by the release workflow",
		"",
		other + "  Exposely-amd64-installer.exe",
		digest + "  Exposely.exe",
		digest + " *./Exposely.exe",
	}, "\n")

	tests := []struct {
		name  string
		asset string
		want  string
	}{
		{"plain entry", "Exposely.exe", digest},
		{"case-insensitive name", "exposely.EXE", digest},
		{"surrounding spaces", "  Exposely.exe  ", digest},
		{"binary-mode star and dot-slash", "./Exposely.exe", digest},
		{"second asset", "Exposely-amd64-installer.exe", other},
	}

	for _, tc := range tests {
		t.Run(tc.name, func(t *testing.T) {
			got, err := FindDigest(sums, tc.asset)
			if err != nil {
				t.Fatalf("FindDigest(%q) returned error: %v", tc.asset, err)
			}
			if got != tc.want {
				t.Fatalf("FindDigest(%q) = %s, want %s", tc.asset, got, tc.want)
			}
		})
	}
}

func TestFindDigestRejectsMissingOrMalformedEntries(t *testing.T) {
	digest := sha256Hex("exposely binary")
	sums := strings.Join([]string{
		"not-a-digest  Exposely.exe",
		"abc  Short.exe",
		digest + "  SomeOtherAsset.exe",
		digest, // digest with no filename
	}, "\n")

	for _, asset := range []string{"Exposely.exe", "Short.exe", "Missing.exe", ""} {
		if got, err := FindDigest(sums, asset); err == nil {
			t.Fatalf("FindDigest(%q) = %q, want an error", asset, got)
		}
	}
}

func TestFindDigestHandlesBOMAndCRLF(t *testing.T) {
	digest := sha256Hex("exposely binary")
	// Out-File on Windows writes CRLF and a BOM unless asked not to; the
	// first asset in the file must still resolve.
	sums := "\ufeff" + digest + "  Exposely.exe\r\n" + sha256Hex("other") + "  Other.exe\r\n"

	got, err := FindDigest(sums, "Exposely.exe")
	if err != nil {
		t.Fatalf("FindDigest with a BOM/CRLF file returned error: %v", err)
	}
	if got != digest {
		t.Fatalf("FindDigest = %s, want %s", got, digest)
	}
}

func TestVerifyFileMatchesAndDetectsTampering(t *testing.T) {
	dir := t.TempDir()
	path := filepath.Join(dir, "Exposely.exe")
	payload := "pretend executable"
	if err := os.WriteFile(path, []byte(payload), 0o644); err != nil {
		t.Fatal(err)
	}

	if err := VerifyFile(path, "Exposely.exe", sha256Hex(payload)); err != nil {
		t.Fatalf("VerifyFile rejected a matching download: %v", err)
	}

	if err := VerifyFile(path, "Exposely.exe", sha256Hex("something else")); err == nil {
		t.Fatal("VerifyFile accepted a download whose digest does not match")
	} else if !strings.Contains(err.Error(), "checksum mismatch") {
		t.Fatalf("unexpected error for a mismatch: %v", err)
	}

	if err := VerifyFile(filepath.Join(dir, "missing.exe"), "Exposely.exe", sha256Hex(payload)); err == nil {
		t.Fatal("VerifyFile accepted a file that does not exist")
	}
}

func TestDigestFileReadsLargeFilesInFull(t *testing.T) {
	dir := t.TempDir()
	path := filepath.Join(dir, "big.bin")

	// Larger than the io.Copy buffer so the hash must span several reads.
	payload := strings.Repeat("exposely", 1024*64)
	if err := os.WriteFile(path, []byte(payload), 0o644); err != nil {
		t.Fatal(err)
	}

	got, err := DigestFile(path)
	if err != nil {
		t.Fatal(err)
	}
	if got != sha256Hex(payload) {
		t.Fatalf("DigestFile = %s, want %s", got, sha256Hex(payload))
	}
}
